<script setup lang="ts">
import { gameName } from '../../shared/games.mjs'
import { singlePrinting } from '../../shared/variant-visuals.mjs'
const props = defineProps<{ card: any }>(), emit = defineEmits(['select'])
function priceText(price: any) { return new Intl.NumberFormat('en-AU', { style: 'currency', currency: price.aud == null ? price.currency : 'AUD' }).format(price.aud ?? price.amount) + (price.aud == null ? ' ' + price.currency : ' AUD') }
</script>
<template><button class="card-tile" @click="emit('select', card.id)"><div class="card-picture"><CardArtwork :card="card" :printing="singlePrinting(card)" /><span v-if="card.quantity > 0" class="owned-badge"><AppIcon name="check" :size="12" />{{ card.quantity }} owned</span><span v-else-if="card.wishlist" class="wish-badge"><AppIcon name="star" :size="14" /></span></div><span class="card-meta"><strong>{{ card.name }}</strong><span>{{ gameName(card.game || 'pokemon') }} · {{ card.set_name }}</span><span v-if="card.visual_printings?.length > 1" class="available-variants"><small>Available printings</small><VariantBadges v-for="p in card.visual_printings" :key="p.key" :printing="p" :show-unknown="true" /></span><span v-if="card.price_from" class="card-market-price">{{ card.price_from.approximate ? 'Approx. from ' : 'From ' }}{{ priceText(card.price_from) }}<small v-if="card.price_from.stale || card.price_from.fetch_error">Stale / check details</small></span><small v-else class="muted">Price not available</small><small>#{{ card.local_id }}<span>{{ card.language.toUpperCase() }}</span></small></span></button></template>
